USE [JamunaBankProcurement];
GO
SET XACT_ABORT ON;
BEGIN TRAN;
INSERT dbo.ORG_UNIT(ORG_UNIT_CODE,ORG_UNIT_NAME,ORG_UNIT_TYPE,CREATED_BY) VALUES
('ICT','ICT Division','DIVISION','seed'),('PROC','Procurement Division','DIVISION','seed'),('FIN','Finance Division','DIVISION','seed'),('HR','HR Division','DIVISION','seed'),('ADMIN','Admin Division','DIVISION','seed'),('GUL-CORP','Gulshan Corporate Branch','BRANCH','seed'),('UTT-BR','Uttara Branch','BRANCH','seed');
INSERT dbo.ROLE_MASTER(ROLE_CODE,ROLE_NAME,CREATED_BY) VALUES
('MAKER','Maker','seed'),('MANAGER','Manager','seed'),('PROCUREMENT_OFFICER','Procurement Officer','seed'),('PROCUREMENT_AUTHORITY','Procurement Authority','seed'),('CONCERN_OFFICIAL','Concern Division Official','seed'),('CONCERN_AUTHORITY','Concern Division Authority','seed'),('PROCUREMENT_TRACKER','Procurement Tracker','seed'),('ADMIN','Administrator','seed');
DECLARE @ict BIGINT=(SELECT ORG_UNIT_ID FROM dbo.ORG_UNIT WHERE ORG_UNIT_CODE='ICT'),@proc BIGINT=(SELECT ORG_UNIT_ID FROM dbo.ORG_UNIT WHERE ORG_UNIT_CODE='PROC'),@gul BIGINT=(SELECT ORG_UNIT_ID FROM dbo.ORG_UNIT WHERE ORG_UNIT_CODE='GUL-CORP');
INSERT dbo.APP_USER_CACHE(EMPLOYEE_ID,DISPLAY_NAME,EMAIL,DESIGNATION,ORG_UNIT_ID) VALUES
('DEV-MAKER-01','Development Maker','maker@example.invalid','Officer',@gul),('DEV-MGR-01','Development Manager','manager@example.invalid','Branch Manager',@gul),('DEV-PO-01','Procurement Officer A','po1@example.invalid','Procurement Officer',@proc),('DEV-PO-02','Procurement Officer B','po2@example.invalid','Procurement Officer',@proc),('DEV-PA-01','Procurement Authority A','pa1@example.invalid','Head of Procurement',@proc),('DEV-PA-02','Procurement Authority B','pa2@example.invalid','Operations Head',@proc),('DEV-CO-01','ICT Concern Official A','co1@example.invalid','ICT Officer',@ict),('DEV-CO-02','ICT Concern Official B','co2@example.invalid','ICT Officer',@ict),('DEV-CA-01','ICT Authority A','ca1@example.invalid','Head of ICT',@ict),('DEV-CA-02','ICT Authority B','ca2@example.invalid','Senior Official',@ict),('DEV-TRACK-01','Procurement Tracker','track@example.invalid','Tracker',@proc),('DEV-ADMIN-01','Development Admin','admin@example.invalid','Administrator',@ict);
INSERT dbo.DEV_USER(EMPLOYEE_ID,USERNAME,PASSWORD_HASH,CREATED_BY) SELECT EMPLOYEE_ID,LOWER(REPLACE(EMPLOYEE_ID,'DEV-','dev.')),CONCAT('DEV_ONLY_NOT_A_REAL_HASH_',EMPLOYEE_ID),'seed' FROM dbo.APP_USER_CACHE;
INSERT dbo.DEV_USER_ROLE(DEV_USER_ID,ROLE_ID,ORG_UNIT_ID,CREATED_BY) SELECT u.DEV_USER_ID,r.ROLE_ID,c.ORG_UNIT_ID,'seed' FROM dbo.DEV_USER u JOIN dbo.APP_USER_CACHE c ON c.EMPLOYEE_ID=u.EMPLOYEE_ID JOIN dbo.ROLE_MASTER r ON r.ROLE_CODE=CASE WHEN u.EMPLOYEE_ID LIKE 'DEV-MAKER%' THEN 'MAKER' WHEN u.EMPLOYEE_ID LIKE 'DEV-MGR%' THEN 'MANAGER' WHEN u.EMPLOYEE_ID LIKE 'DEV-PO-%' THEN 'PROCUREMENT_OFFICER' WHEN u.EMPLOYEE_ID LIKE 'DEV-PA-%' THEN 'PROCUREMENT_AUTHORITY' WHEN u.EMPLOYEE_ID LIKE 'DEV-CO-%' THEN 'CONCERN_OFFICIAL' WHEN u.EMPLOYEE_ID LIKE 'DEV-CA-%' THEN 'CONCERN_AUTHORITY' WHEN u.EMPLOYEE_ID LIKE 'DEV-TRACK%' THEN 'PROCUREMENT_TRACKER' ELSE 'ADMIN' END;
INSERT dbo.ASSET_CATEGORY(CATEGORY_CODE,CATEGORY_NAME,CREATED_BY) VALUES('IT','Information Technology','seed'),('OFFICE','Office Equipment','seed'),('FACILITY','Facility Equipment','seed');
DECLARE @it BIGINT=(SELECT ASSET_CATEGORY_ID FROM dbo.ASSET_CATEGORY WHERE CATEGORY_CODE='IT'),@off BIGINT=(SELECT ASSET_CATEGORY_ID FROM dbo.ASSET_CATEGORY WHERE CATEGORY_CODE='OFFICE'),@fac BIGINT=(SELECT ASSET_CATEGORY_ID FROM dbo.ASSET_CATEGORY WHERE CATEGORY_CODE='FACILITY');
INSERT dbo.ASSET_MASTER(ASSET_CATEGORY_ID,ASSET_CODE,ASSET_NAME,UNIT_OF_MEASUREMENT,DEFAULT_WARRANTY,USEFUL_LIFE,CRITICALITY,IS_INVENTORY_ITEM,IS_DEPRECIABLE,CREATED_BY) VALUES
(@it,'DESKTOP','Desktop Computer','Unit',36,5,'HIGH',1,1,'seed'),(@it,'LAPTOP','Laptop','Unit',36,4,'HIGH',1,1,'seed'),(@off,'PRINTER','Printer','Unit',24,5,'MEDIUM',1,1,'seed'),(@off,'SCANNER','Scanner','Unit',24,5,'MEDIUM',1,1,'seed'),(@fac,'AC','Air Conditioner','Unit',24,8,'MEDIUM',1,1,'seed'),(@it,'UPS','UPS','Unit',24,4,'MEDIUM',1,1,'seed'),(@it,'SERVER','Server','Unit',36,5,'CRITICAL',1,1,'seed'),(@it,'SWITCH','Network Switch','Unit',36,5,'CRITICAL',1,1,'seed');
DECLARE @desktop BIGINT=(SELECT ASSET_ID FROM dbo.ASSET_MASTER WHERE ASSET_CODE='DESKTOP'),@printer BIGINT=(SELECT ASSET_ID FROM dbo.ASSET_MASTER WHERE ASSET_CODE='PRINTER'),@ac BIGINT=(SELECT ASSET_ID FROM dbo.ASSET_MASTER WHERE ASSET_CODE='AC');
