INSERT dbo.ASSET_SPEC_OPTION(ASSET_SPEC_ID,OPTION_VALUE,DISPLAY_ORDER,CREATED_BY) SELECT ASSET_SPEC_ID,v,o,'seed' FROM (VALUES('Processor','Intel Core i5',1),('Processor','Intel Core i7',2),('Storage','512 GB SSD',1),('Storage','1 TB HDD',2),('Operating System','Windows 11 Pro',1),('Printer Type','Laser',1),('Printer Type','Inkjet',2),('Print Mode','Monochrome',1),('Print Mode','Color',2),('Energy Rating','3 Star',1),('Energy Rating','5 Star',2)) x(n,v,o) JOIN dbo.ASSET_SPEC_DEFINITION d ON d.SPEC_NAME=x.n;
